           "key": "book.mol.opposition",
           "stage": "seen",
           "value": "You actually saw a human scavenger with a short reach hook at this hatch. A hook strike can reach the exposed edge; smoke and oily footing make an unprepared reach costly. Their deeper associates and motives beyond salvage are unknown. Prepared keyed light, a current tether, willing Taiven, an actual food/payment bargain or retreat provide bounded alternatives.",
