       "cue": "The watch lies beyond the oily edge while the scavenger blocks the short route. Prepared light guides a narrow reach; ordinary oil light leaves smoke; willing Taiven can spend her own trained means to stop the blocker; a real bargain can buy one stand-aside. A rush loses health and closes the attempt. You may retreat.",
